//#region src/game/actors.ts
/** Runner + chaser kangaroo visuals driven from engine state. */
var Actors = class {
	rig;
	chaser;
	chaserBubble;
	kangaroo;
	wheels;
	textures = [];
	showBubbleWhenFlying;
	constructor(scene, character, skin) {
		const face = stickerTexture(skin.imagePath, skin.accentColor);
		const bubble = bubbleTexture(character.catchphrase);
		const roo = stickerTexture(CHASER.imagePath, CHASER.accentColor);
		const caught = bubbleTexture(CHASER_RULES.caughtText);
		this.textures.push(face, bubble, roo, caught);
		this.showBubbleWhenFlying = character.catchphraseTrigger === "flight";
		this.rig = makeRunner(skin.accentColor, face, bubble);
		scene.add(this.rig.root, this.rig.shadow);
		this.chaser = new Group();
		const scooter = makeScooter("#ffc300", "#ffd60a");
		scooter.rotation.y = Math.PI;
		this.chaser.add(scooter);
		this.wheels = scooter.children.filter((c) => c.name === "wheel");
		this.kangaroo = sprite(roo, 1.8);
		this.kangaroo.position.set(0, 2.15, 0);
		this.chaser.add(this.kangaroo);
		this.chaserBubble = sprite(caught, 3);
		this.chaserBubble.scale.set(4.4, 1.5, 1);
		this.chaserBubble.position.set(.4, 3.9, 0);
		this.chaser.add(this.chaserBubble);
		scene.add(this.chaser);
	}
	update(s, time) {
		const r = s.runner;
		const rig = this.rig;
		const caught = s.status !== "running";
		const rolling = r.rollTimer > 0;
		const flying = isFlying(s);
		const ult = s.active.naiFamilyUltimate > 0;
		rig.root.position.set(r.x, r.y, 0);
		rig.shadow.position.x = r.x;
		const sh = Math.max(.35, 1 - r.y * .12);
		rig.shadow.scale.set(sh, sh, sh);
		const swing = caught ? 0 : Math.sin(r.stride * .55);
		const air = !r.grounded && !flying;
		rig.legL.rotation.x = air ? -.9 : swing * .95;
		rig.legR.rotation.x = air ? -.4 : -swing * .95;
		rig.armL.rotation.x = -swing * .8 - (flying ? 2.4 : 0);
		rig.armR.rotation.x = swing * .8 - (flying ? 2.4 : 0);
		const lean = (r.x - Math.round(r.x / LANE_WIDTH) * LANE_WIDTH) * -.25;
		rig.body.rotation.z = caught ? .55 : lean;
		if (rolling) {
			rig.body.scale.set(1.1, .5, 1.1);
			rig.body.rotation.x = -time * 18;
		} else {
			const bob = r.grounded ? Math.abs(swing) * .06 : 0;
			rig.body.scale.set(1, 1 + bob, 1);
			rig.body.rotation.x = caught ? -.4 : 0;
		}
		rig.face.scale.setScalar(caught ? 1.6 : 1.35);
		const blink = s.invulnTimer > 0 && !ult && Math.sin(time * 40) > 0;
		rig.body.visible = !blink;
		rig.shield.visible = s.active.milkShield > 0;
		rig.shield.scale.setScalar(1 + Math.sin(time * 6) * .05);
		rig.flames.visible = flying;
		rig.flames.scale.set(1, .8 + Math.random() * .6, 1);
		rig.aura.visible = ult;
		rig.aura.rotation.y = time * 6;
		rig.aura.scale.setScalar(1 + Math.sin(time * 10) * .15);
		const shout = this.showBubbleWhenFlying ? flying || r.y > 1.2 : ult;
		rig.bubble.visible = shout && !caught;
		if (shout) rig.bubble.position.y = 3.1 + Math.sin(time * 9) * .08;
		const z = Math.min(9, .9 + s.chaserGap * .42);
		const side = caught ? .7 : 1.4;
		const cx = this.chaser.position.x;
		this.chaser.position.set(cx + (r.x + side - cx) * .12, Math.sin(time * 12) * .04, z);
		this.chaser.rotation.z = Math.sin(time * 3) * .05;
		for (const w of this.wheels) w.rotation.x -= caught ? 0 : .6;
		this.kangaroo.scale.setScalar(caught ? 2.2 : 1.8);
		this.chaserBubble.visible = caught;
	}
};
//#endregion
//#region src/game/city.ts
var BUILDING_STEP = 14;
var SPAN = 252;
var SIGN_COUNT = 14;
var GANTRY_SPAN = 160;
var DRONE_COUNT = 7;
var SIGN_DEFS = [
	{
		text: "奶家人",
		color: "#ffd60a"
	},
	{
		text: "鼠家人",
		color: "#22d3ee"
	},
	{
		text: "奶家人",
		color: "#ff3fa4"
	},
	{
		text: "鼠家人",
		color: "#a855f7"
	}
];
/** Recycling neon city: buildings, animated signs, gantries and drones. */
var City = class {
	buildings = [];
	signs = [];
	drones = [];
	buildingMats = [];
	textures = [];
	constructor(scene) {
		const win = windowTexture();
		this.textures.push(win);
		for (const c of [
			"#2b1857",
			"#3b1f6e",
			"#1f2a5c",
			"#4a1d5e"
		]) {
			const m = new MeshStandardMaterial({
				color: c,
				emissive: new Color("#ffffff"),
				emissiveMap: win,
				emissiveIntensity: .6,
				roughness: .8
			});
			this.buildingMats.push(m);
		}
		const geo = new BoxGeometry(1, 1, 1).translate(0, .5, 0);
		for (let i = 0; i < 36; i++) {
			const side = i % 2 === 0 ? -1 : 1;
			const mesh = new Mesh(geo, this.buildingMats[i % 4]);
			const b = {
				mesh,
				side,
				at: Math.floor(i / 2) * BUILDING_STEP
			};
			this.shapeBuilding(b);
			scene.add(mesh);
			this.buildings.push(b);
		}
		const signTex = SIGN_DEFS.map((d) => neonSignTexture(d.text, d.color));
		this.textures.push(...signTex);
		const plane = new PlaneGeometry(1, .375);
		for (let i = 0; i < 16; i++) {
			const tex = signTex[i % signTex.length];
			const mat = new MeshStandardMaterial({
				color: "#111111",
				map: tex,
				emissive: new Color("#ffffff"),
				emissiveMap: tex,
				transparent: true,
				emissiveIntensity: 1
			});
			const mesh = new Mesh(plane, mat);
			const gantry = i >= SIGN_COUNT;
			if (gantry) {
				mesh.scale.set(7.5, 7.5, 1);
				mesh.position.set(0, 7.4, 0);
			} else {
				const side = i % 2 === 0 ? -1 : 1;
				mesh.scale.set(4.2, 4.2, 1);
				mesh.rotation.y = -side * (Math.PI / 2 - .35);
				mesh.position.set(side * 6.9, 4 + i % 3 * 2.2, 0);
			}
			scene.add(mesh);
			this.signs.push({
				mesh,
				mat,
				phase: Math.random() * 10,
				span: gantry ? 320 : SPAN,
				at: gantry ? 90 + (i - SIGN_COUNT) * GANTRY_SPAN : 20 + i * SPAN / SIGN_COUNT
			});
		}
		for (let i = 0; i < DRONE_COUNT; i++) {
			const group = makeDrone();
			scene.add(group);
			this.drones.push({
				group,
				at: 30 + i * 22,
				x: (Math.random() - .5) * 14,
				y: 6 + Math.random() * 4,
				phase: Math.random() * 6,
				lamp: group.children.find((c) => c.name === "lamp")
			});
		}
	}
	shapeBuilding(b) {
		const w = 4 + Math.random() * 5;
		const h = 8 + Math.random() * 26;
		const d = 8 + Math.random() * 5;
		b.mesh.scale.set(w, h, d);
		b.mesh.position.x = b.side * (7.8 + w / 2 + Math.random() * 1.5);
	}
	update(distance, dt, time, neon) {
		for (const b of this.buildings) {
			if (b.at - distance < -20) {
				b.at += SPAN;
				this.shapeBuilding(b);
			}
			b.mesh.position.z = -(b.at - distance);
		}
		for (const m of this.buildingMats) m.emissiveIntensity = .15 + neon * .45;
		for (const s of this.signs) {
			if (s.at - distance < -20) s.at += s.span;
			s.mesh.position.z = -(s.at - distance);
			const pulse = .78 + .22 * Math.sin(time * 4 + s.phase);
			const flicker = Math.sin(time * 23 + s.phase * 7) > .97 ? .25 : 1;
			s.mat.emissiveIntensity = (.4 + neon) * pulse * flicker;
		}
		for (const d of this.drones) {
			d.at += dt * 4;
			if (d.at - distance < -15) {
				d.at += 160;
				d.x = (Math.random() - .5) * 14;
				d.y = 6 + Math.random() * 4;
			}
			const g = d.group;
			g.position.set(d.x + Math.sin(time * .8 + d.phase) * 2, d.y + Math.sin(time * 2 + d.phase) * .35, -(d.at - distance));
			g.rotation.z = Math.sin(time * 1.3 + d.phase) * .12;
			if (d.lamp) d.lamp.visible = Math.sin(time * 8 + d.phase) > 0;
		}
	}
};
//#endregion
//#region src/game/dayNight.ts
var LOOK = {
	day: {
		fog: "#BFE3FF",
		ambient: 1.25,
		sun: 1.6,
		neon: .55,
		fogNear: 60
	},
	dusk: {
		fog: "#C85A8A",
		ambient: .85,
		sun: .9,
		neon: 1.3,
		fogNear: 45
	},
	neonNight: {
		fog: "#2A1250",
		ambient: .5,
		sun: .25,
		neon: 2.6,
		fogNear: 30
	},
	dawn: {
		fog: "#E9B7D8",
		ambient: 1,
		sun: 1.1,
		neon: .9,
		fogNear: 50
	}
};
var BLEND = 260;
var PRESETS = DAY_PHASES.map((p) => ({
	top: new Color(p.skyTop),
	bottom: new Color(p.skyBottom),
	fog: new Color(LOOK[p.id].fog),
	look: LOOK[p.id],
	start: p.startDistance
}));
function createAtmosphere() {
	return {
		skyTop: new Color(),
		skyBottom: new Color(),
		fog: new Color(),
		ambient: 1,
		sun: 1,
		neon: 1,
		fogNear: 50
	};
}
/** Writes the blended atmosphere for `distance` into `out` (no allocations). */
function sampleAtmosphere(distance, out) {
	const d = (distance % DAY_CYCLE_LENGTH + DAY_CYCLE_LENGTH) % DAY_CYCLE_LENGTH;
	const phase = phaseAtDistance(distance);
	const i = DAY_PHASES.indexOf(phase);
	const cur = PRESETS[i];
	const next = PRESETS[(i + 1) % PRESETS.length];
	const end = i + 1 < PRESETS.length ? next.start : DAY_CYCLE_LENGTH;
	const t = Math.min(1, Math.max(0, (d - (end - BLEND)) / BLEND));
	const e = t * t * (3 - 2 * t);
	out.skyTop.copy(cur.top).lerp(next.top, e);
	out.skyBottom.copy(cur.bottom).lerp(next.bottom, e);
	out.fog.copy(cur.fog).lerp(next.fog, e);
	out.ambient = cur.look.ambient + (next.look.ambient - cur.look.ambient) * e;
	out.sun = cur.look.sun + (next.look.sun - cur.look.sun) * e;
	out.neon = cur.look.neon + (next.look.neon - cur.look.neon) * e;
	out.fogNear = cur.look.fogNear + (next.look.fogNear - cur.look.fogNear) * e;
}
//#endregion
//#region src/game/effects.ts
var HIDDEN = -999;
/** Pooled burst particles (coin sparkles, power-up bursts, smash debris). */
var Sparkles = class {
	count;
	points;
	pos;
	col;
	vel;
	life;
	cursor = 0;
	constructor(count, tex) {
		this.count = count;
		this.pos = new Float32Array(count * 3).fill(HIDDEN);
		this.col = new Float32Array(count * 3);
		this.vel = new Float32Array(count * 3);
		this.life = new Float32Array(count);
		const geo = new BufferGeometry();
		geo.setAttribute("position", new BufferAttribute(this.pos, 3));
		geo.setAttribute("color", new BufferAttribute(this.col, 3));
		const mat = new PointsMaterial({
			size: .42,
			map: tex,
			vertexColors: true,
			transparent: true,
			depthWrite: false,
			blending: 2
		});
		this.points = new Points(geo, mat);
		this.points.frustumCulled = false;
	}
	emit(x, y, z, n, color, power = 5) {
		for (let k = 0; k < n; k++) {
			const i = this.cursor;
			this.cursor = (this.cursor + 1) % this.count;
			const a = Math.random() * Math.PI * 2;
			const u = Math.random() * 2 - 1;
			const s = power * (.4 + Math.random() * .6);
			const r = Math.sqrt(1 - u * u);
			this.pos[i * 3] = x;
			this.pos[i * 3 + 1] = y;
			this.pos[i * 3 + 2] = z;
			this.vel[i * 3] = Math.cos(a) * r * s;
			this.vel[i * 3 + 1] = Math.abs(u) * s + 1.5;
			this.vel[i * 3 + 2] = Math.sin(a) * r * s;
			this.col[i * 3] = color.r;
			this.col[i * 3 + 1] = color.g;
			this.col[i * 3 + 2] = color.b;
			this.life[i] = .5 + Math.random() * .4;
		}
	}
	update(dt, scroll) {
		for (let i = 0; i < this.count; i++) {
			if (this.life[i] <= 0) continue;
			this.life[i] -= dt;
			if (this.life[i] <= 0) {
				this.pos[i * 3 + 1] = HIDDEN;
				continue;
			}
			this.vel[i * 3 + 1] -= 9 * dt;
			this.pos[i * 3] += this.vel[i * 3] * dt;
			this.pos[i * 3 + 1] += this.vel[i * 3 + 1] * dt;
			this.pos[i * 3 + 2] += (this.vel[i * 3 + 2] + scroll) * dt;
			const fade = Math.min(1, this.life[i] * 2.5);
			this.col[i * 3] *= .985 + .015 * fade;
		}
		const geo = this.points.geometry;
		geo.attributes.position.needsUpdate = true;
		geo.attributes.color.needsUpdate = true;
	}
};
/** Light drifting particle weather (glitter / drizzle) around the camera. */
var Weather = class {
	count;
	points;
	pos;
	material;
	constructor(count, tex) {
		this.count = count;
		this.pos = new Float32Array(count * 3);
		for (let i = 0; i < count; i++) {
			this.pos[i * 3] = (Math.random() - .5) * 40;
			this.pos[i * 3 + 1] = Math.random() * 18;
			this.pos[i * 3 + 2] = -Math.random() * 90 + 10;
		}
		const geo = new BufferGeometry();
		geo.setAttribute("position", new BufferAttribute(this.pos, 3));
		this.material = new PointsMaterial({
			size: .16,
			map: tex,
			color: "#ffffff",
			transparent: true,
			opacity: .7,
			depthWrite: false,
			blending: 2
		});
		this.points = new Points(geo, this.material);
		this.points.frustumCulled = false;
	}
	update(dt, speed, time) {
		const fall = 2.4 * dt;
		const scroll = speed * .55 * dt;
		for (let i = 0; i < this.count; i++) {
			const j = i * 3;
			this.pos[j] += Math.sin(time * .7 + i) * .6 * dt;
			this.pos[j + 1] -= fall;
			this.pos[j + 2] += scroll;
			if (this.pos[j + 1] < 0) this.pos[j + 1] += 18;
			if (this.pos[j + 2] > 10) this.pos[j + 2] -= 100;
		}
		this.points.geometry.attributes.position.needsUpdate = true;
	}
};
/** Streaking speed lines that trail past the runner. */
var SpeedLines = class {
	count;
	lines;
	material;
	pos;
	seed;
	constructor(count) {
		this.count = count;
		this.pos = new Float32Array(count * 6);
		this.seed = new Float32Array(count * 3);
		for (let i = 0; i < count; i++) {
			const side = i % 2 === 0 ? -1 : 1;
			this.seed[i * 3] = side * (1.2 + Math.random() * 4.5);
			this.seed[i * 3 + 1] = .3 + Math.random() * 3.8;
			this.seed[i * 3 + 2] = -Math.random() * 40;
		}
		const geo = new BufferGeometry();
		geo.setAttribute("position", new BufferAttribute(this.pos, 3));
		this.material = new LineBasicMaterial({
			color: "#e8f8ff",
			transparent: true,
			opacity: .3,
			depthWrite: false,
			blending: 2
		});
		this.lines = new LineSegments(geo, this.material);
		this.lines.frustumCulled = false;
	}
	update(dt, speed, runnerX, boost) {
		const len = .6 + speed * .09 * (boost ? 2 : 1);
		const v = speed * (boost ? 2.6 : 1.7) * dt;
		for (let i = 0; i < this.count; i++) {
			const s = i * 3;
			this.seed[s + 2] += v;
			if (this.seed[s + 2] > 7) this.seed[s + 2] -= 45;
			const p = i * 6;
			const x = this.seed[s] + runnerX;
			this.pos[p] = x;
			this.pos[p + 1] = this.seed[s + 1];
			this.pos[p + 2] = this.seed[s + 2];
			this.pos[p + 3] = x;
			this.pos[p + 4] = this.seed[s + 1];
			this.pos[p + 5] = this.seed[s + 2] - len;
		}
		this.lines.geometry.attributes.position.needsUpdate = true;
		const intensity = Math.min(1, (speed - 12) / 30);
		this.material.opacity = boost ? .9 : .12 + intensity * .55;
	}
};
