/** Derives card view + actions for a shop item from the persisted progress store. */
function useShopItem(item) {
	const coins = useCoins();
	const { character: equippedCharacter, skin: equippedSkin } = useEquipped();
	const { unlockedSkinIds, unlockedCharacterIds } = useUnlocks();
	const { unlockSkin, unlockCharacter, equipSkin, equipCharacter } = useProgressActions();
	let view;
	let owned;
	let equipped;
	let lockedReason = null;
	if (item.kind === "character") {
		const c = item.character;
		owned = unlockedCharacterIds.includes(c.id);
		equipped = equippedCharacter.id === c.id;
		view = {
			id: c.id,
			name: c.name,
			description: c.description,
			price: c.price,
			imagePath: c.imagePath,
			accent: c.accentColor,
			status: { state: "owned" }
		};
	} else {
		const s = item.skin;
		owned = isSkinUsable(s.id, unlockedSkinIds, unlockedCharacterIds);
		equipped = equippedSkin.id === s.id;
		if (!owned && !unlockedCharacterIds.includes(s.characterId)) lockedReason = `需先解锁${getCharacter(s.characterId).name}`;
		view = {
			id: s.id,
			name: s.name,
			description: s.description,
			price: s.price,
			imagePath: s.imagePath,
			accent: s.accentColor,
			status: { state: "owned" }
		};
	}
	if (equipped) view.status = { state: "equipped" };
	else if (owned) view.status = { state: "owned" };
	else if (lockedReason) view.status = {
		state: "locked",
		reason: lockedReason
	};
	else if (canAfford(coins, view.price)) view.status = { state: "affordable" };
	else view.status = {
		state: "short",
		shortfall: view.price - coins
	};
	const equip = () => {
		if (item.kind === "character") equipCharacter(item.character.id);
		else {
			if (item.skin.characterId !== equippedCharacter.id) equipCharacter(item.skin.characterId);
			equipSkin(item.skin.id);
		}
		ue.success(`已装备 ${view.name}`, { duration: 4e3 });
	};
	/** Store unlock actions spend the price themselves; returns true on success. */
	const unlock = () => {
		if (!(item.kind === "character" ? unlockCharacter(item.character.id) : unlockSkin(item.skin.id))) {
			ue.error("金币不足，再去跑几圈吧！", { duration: 4e3 });
			return false;
		}
		if (item.kind === "character") equipCharacter(item.character.id);
		else {
			if (item.skin.characterId !== equippedCharacter.id) equipCharacter(item.skin.characterId);
			equipSkin(item.skin.id);
		}
		ue.success("解锁成功！", {
			description: `${view.name} 已自动装备`,
			duration: 5e3
		});
		return true;
	};
	return {
		view,
		equip,
		unlock
	};
}
